import{_ as t,c as r,o as a,ag as i}from"./chunks/framework.CQuhCYrb.js";const g=JSON.parse('{"title":"Element (Matrix) Messenger","description":"","frontmatter":{"title":"Element (Matrix) Messenger"},"headers":[],"relativePath":"matrix/element-matrix-messenger.md","filePath":"matrix/element-matrix-messenger.md","lastUpdated":null}'),o={name:"matrix/element-matrix-messenger.md"};function n(s,e,l,d,c,u){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="element-matrix-messenger" tabindex="-1">Element (Matrix) Messenger <a class="header-anchor" href="#element-matrix-messenger" aria-label="Permalink to &quot;Element (Matrix) Messenger&quot;">​</a></h1><ol><li>🚀 Exploring Element Messenger Welcome to Element Messenger, a powerful Matrix client designed for seamless communication. This guide will help you navigate its features and start your journey with Element efficiently.</li></ol><h3 id="what-makes-element-unique-🌟" tabindex="-1">What Makes Element Unique? 🌟 <a class="header-anchor" href="#what-makes-element-unique-🌟" aria-label="Permalink to &quot;What Makes Element Unique? 🌟&quot;">​</a></h3><p>Element stands out due to its robust features tailored for group communications:</p><ul><li><p><strong>🕵️ Anonymity</strong>: Sign up with just a username; no phone number required.</p></li><li><p><strong>🌐 Accessibility</strong>: Accessible on NIPR via the web. Self-hosting may be required for enhanced privacy.</p></li><li><p><strong>📣 Custom Notifications</strong>: Set up alerts for specific keywords to stay focused on relevant discussions.</p></li><li><p><strong>💬 Organized Chats</strong>: Utilize threads to keep conversations streamlined and organized.</p></li></ul><p><em>[Element]</em></p><p>Explore the capabilities of Element on <a href="https://matrix.irregularchat.com" target="_blank" rel="noreferrer">Matrix Chat</a>. While Matrix and Element are often used interchangeably, numerous clients are available across different platforms.</p><h3 id="essential-resources" tabindex="-1">Essential Resources <a class="header-anchor" href="#essential-resources" aria-label="Permalink to &quot;Essential Resources&quot;">​</a></h3><ul><li><p><a href="https://static.element.io/pdfs/element-user-guide.pdf" target="_blank" rel="noreferrer">Official Element User Guide</a></p></li><li><p>[Matrix on Wikipedia](<a href="https://en.wikipedia.org/wiki/Matrix_(protocol)" target="_blank" rel="noreferrer">https://en.wikipedia.org/wiki/Matrix_(protocol)</a></p></li><li><p><a href="https://matrix.org/docs/chat_basics/matrix-for-im/" target="_blank" rel="noreferrer">Learn More About Matrix</a></p></li><li><p><a href="https://nebuchadnezzar-megolm.github.io/static/paper.pdf" target="_blank" rel="noreferrer">Deep Dive Into Matrix Protocol</a></p></li></ul><p>📥 <strong><a href="https://element.io/download" target="_blank" rel="noreferrer">Download Element Messenger</a></strong> available for Desktop, Android, iOS, and Web.</p><h3 id="using-matrix-with-the-irregular-chat-login-🔑" tabindex="-1">Using Matrix with the Irregular Chat Login 🔑 <a class="header-anchor" href="#using-matrix-with-the-irregular-chat-login-🔑" aria-label="Permalink to &quot;Using Matrix with the Irregular Chat Login 🔑&quot;">​</a></h3><h3 id="navigating-element-messenger" tabindex="-1">Navigating Element Messenger <a class="header-anchor" href="#navigating-element-messenger" aria-label="Permalink to &quot;Navigating Element Messenger&quot;">​</a></h3><p>When selecting a Matrix link, choose <strong>“Continue using Element”</strong> for a smooth experience.</p><h3 id="get-started" tabindex="-1">Get Started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get Started&quot;">​</a></h3><h4 id="logging-in" tabindex="-1">Logging In <a class="header-anchor" href="#logging-in" aria-label="Permalink to &quot;Logging In&quot;">​</a></h4><p><strong>Ensure you are logged out from any other Matrix accounts, or use a separate client like Fluffy Chat.</strong></p><ul><li><p><strong>Download and Install Element</strong>: Available on <a href="https://element.io/download" target="_blank" rel="noreferrer">Desktop and Mobile</a>.</p></li><li><p><strong>Configure and Login</strong>:</p><ul><li>Navigate to <a href="https://matrix.irregularchat.com" target="_blank" rel="noreferrer">Matrix Chat</a> or directly open the Element App.</li><li>Select <strong>“I already have an account”</strong> or <strong>“Login”</strong>.</li><li>Set the Homeserver to <code>matrix.irregularchat.com</code> without adding “HTTPS://”.</li><li>Follow prompts to update the homeserver. Login buttons will appear afterward.</li></ul></li><li><p><strong>Account Setup</strong>:</p><ul><li>Choose <strong>“IrregularChat SSO”</strong> or the Puzzle Piece Login 🧩.</li><li>You may ignore any upgrade notices.</li></ul></li></ul><h4 id="security-setup" tabindex="-1">Security Setup <a class="header-anchor" href="#security-setup" aria-label="Permalink to &quot;Security Setup&quot;">​</a></h4><ul><li><strong>Secure Your Account</strong>: <ul><li><strong>Security Phrase</strong>: Create a security phrase and store it in a password manager. <a href="https://ems-docs.element.io/books/element-cloud-documentation/page/set-up-cross-signing" target="_blank" rel="noreferrer">Cross signing guide With Pictures</a>.</li><li><strong>Cross-Device Signing</strong>: Enable if using multiple devices to maintain security across all. Navigate to <strong>Settings</strong> → <strong>Security &amp; Privacy</strong> → <strong>Cryptography</strong>.</li><li>If you didn’t set a recovery key the first time, reset your cross-device signing with this <a href="https://ems-docs.element.io/books/element-cloud-documentation/page/reset-cross-signing" target="_blank" rel="noreferrer">guide</a>.</li><li>Avoid setting restrictions on sending encrypted messages to unverified sessions. Do NOT enable <strong>Never send encrypted messages to unverified sessions from this session</strong>.</li></ul></li></ul><h4 id="joining-spaces" tabindex="-1">Joining Spaces <a class="header-anchor" href="#joining-spaces" aria-label="Permalink to &quot;Joining Spaces&quot;">​</a></h4><ul><li><strong>Join the Conversation</strong>: Enter the Irregular Chat <a href="http://url.irregular.chat/matrix-public" target="_blank" rel="noreferrer">Public Entrance Space</a>.</li><li><strong>Direct message one of the admins to be added to additional chats</strong>: <ul><li><a href="https://matrix.to/#/@sac:irregularchat.com" target="_blank" rel="noreferrer">@sac</a></li><li><a href="https://matrix.to/#/@asymmetricfox:irregularchat.com" target="_blank" rel="noreferrer">@asymmetricfox</a></li><li><a href="https://matrix.to/#/@dog142g:irregularchat.com" target="_blank" rel="noreferrer">@dog142g</a></li><li><a href="https://matrix.to/#/@jumson:irregularchat.com" target="_blank" rel="noreferrer">@jumson</a></li></ul></li><li><strong>Accept Invites</strong>: You should receive invites to the <a href="https://matrix.to/#/!OcvzfbMBIgiwxTDcwY:irregularchat.com" target="_blank" rel="noreferrer">Main Space</a> (Without the invite, these links will not work).</li></ul><p><strong>On the bottom of your screen</strong>, select the icon resembling 4 boxes. Go to the <strong>“All Chats”</strong> tab to see your invitations. Select the <strong>“&gt;”</strong> within spaces to see additional spaces and rooms.</p><ul><li><strong>Enter Spaces</strong>: <ul><li>On the bottom of your screen, select the notepad icon.</li><li>Select <strong>browse spaces</strong>.</li></ul></li></ul><h4 id="customize-your-experience" tabindex="-1">Customize Your Experience <a class="header-anchor" href="#customize-your-experience" aria-label="Permalink to &quot;Customize Your Experience&quot;">​</a></h4><ul><li><strong>Personalize Your Nickname</strong>: Use <code>/myroomnick NewUsernameHere</code> in each room to set a unique nickname.</li><li><strong>Customize Notifications</strong>: Go to <strong>Settings</strong> → <strong>Notifications</strong><ul><li>Custom to set custom notification keywords.</li></ul></li><li><strong>Spaces and Rooms</strong>: When added to the Irregular Chat Space, look for the four (4) boxes to reveal the spaces and rooms within the Irregular Chat Space.</li><li><strong>Bots and Easter Eggs</strong>: Bots will assist with welcome messages and when you post social or news links.</li></ul><p><strong>Inside Jokes</strong>: If you have been in the community for a while, you will know that some running jokes or phrases typically produce a response. Now, it is automated.</p><p><strong>Social Link Proxy</strong>: Twitter, Instagram, and TikTok links will receive a proxy or server download.</p><p>Additional sections are from the <a href="https://static.element.io/pdfs/element-user-guide.pdf" target="_blank" rel="noreferrer">Official Element User Guide</a>.</p><h4 id="secure-backup-encryption-keys-security-phrase" tabindex="-1">Secure Backup - Encryption Keys / Security Phrase <a class="header-anchor" href="#secure-backup-encryption-keys-security-phrase" aria-label="Permalink to &quot;Secure Backup - Encryption Keys / Security Phrase&quot;">​</a></h4><p><a href="https://ems-docs.element.io/books/element-cloud-documentation/page/set-up-cross-signing" target="_blank" rel="noreferrer">Secure Backup</a> - <em>See Element User Guide for Backup details</em></p><h4 id="device-verification" tabindex="-1">Device Verification <a class="header-anchor" href="#device-verification" aria-label="Permalink to &quot;Device Verification&quot;">​</a></h4><p><em>See Element User Guide for Device Verification details</em></p><h4 id="threads" tabindex="-1">Threads <a class="header-anchor" href="#threads" aria-label="Permalink to &quot;Threads&quot;">​</a></h4><p><em>See Element User Guide for Threads details</em></p><h4 id="spaces-and-rooms" tabindex="-1">Spaces and Rooms <a class="header-anchor" href="#spaces-and-rooms" aria-label="Permalink to &quot;Spaces and Rooms&quot;">​</a></h4><p><em>See Element User Guide for Spaces details</em></p><h4 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h4><p><em>See Element User Guide for Notification settings</em></p><h3 id="additional-tips-🚨" tabindex="-1">Additional Tips 🚨 <a class="header-anchor" href="#additional-tips-🚨" aria-label="Permalink to &quot;Additional Tips 🚨&quot;">​</a></h3><p><strong>Prioritize Your Privacy</strong>: Enjoy confidential conversations with default end-to-end encryption, cross-signed device verification, and decentralization, allowing you the autonomy to choose your data’s residence. Create an account without divulging your phone number for added privacy and security.</p><p><strong>Stay Updated</strong>: Keep abreast of known vulnerabilities and update your IrregularChat Matrix Server regularly for optimal security. The server and the client are updated automatically. Please keep your Element app up to date.</p><table tabindex="0"><thead><tr><th>CVE</th><th>Version Patched</th><th>Brief Description</th><th>Part Vulnerable</th></tr></thead><tbody><tr><td>CVE-2022-31052</td><td>1.61.1</td><td>Stack exhaustion in Synapse due to unbounded recursion</td><td>URL previews of some web pages</td></tr><tr><td>CVE-2022-23597</td><td>1.9.7</td><td>Remote program execution bug with user interaction</td><td>Element Desktop before 1.9.7</td></tr><tr><td>CVE-2021-41281</td><td>1.47.1</td><td>File download from a remote server into an arbitrary directory</td><td>Synapse instances with media repository enabled</td></tr><tr><td>CVE-2021-39163</td><td>1.41.0</td><td>Unauthorized access to name, avatar, topic, and number of members</td><td>Homeservers with untrusted users permitted to create groups</td></tr><tr><td>CVE-2021-39164</td><td>1.41.0</td><td>Unauthorized access to membership of a room</td><td>Rooms with <code>shared</code> history visibility</td></tr><tr><td>CVE-2021-32659</td><td>2.6.1</td><td>Unbridging without verifying predecessor field</td><td>Bridges with room upgrade handling</td></tr><tr><td>CVE-2021-32622</td><td>3.21.0</td><td>Script execution in uploaded file preview</td><td>File upload preview before 3.21.0</td></tr><tr><td>CVE-2021-29471</td><td>1.33.2</td><td>Denial-of-service via poor matching engine performance</td><td>Synapse before version 1.33.2</td></tr></tbody></table><h3 id="references-📚" tabindex="-1">References 📚 <a class="header-anchor" href="#references-📚" aria-label="Permalink to &quot;References 📚&quot;">​</a></h3><ul><li><a href="https://element.io/personal" target="_blank" rel="noreferrer">Element Website</a></li></ul><p>[Secure Communication]</p><p>[Blue Team] [Community Guides]</p>',46)])])}const m=t(o,[["render",n]]);export{g as __pageData,m as default};
